void free_tree(Node *root) {
    if (root == NULL) {
        return;
    }

    free_tree(root->left);
    free_tree(root->right);

    free(root);
}

void destroy_tree(Node **rootp) {
    if (rootp == NULL || *rootp == NULL) {
        return;
    }

    Node *root = *rootp;

    destroy_tree(&root->left);
    destroy_tree(&root->right);

    free(root);
    *rootp = NULL;
}
